const hash = new Spatial.SpatialHash(64)

hash.insert('player', { x: 100, y: 100, width: 32, height: 32 })
hash.insert('enemy1', { x: 140, y: 110, width: 32, height: 32 })
hash.insert('enemy2', { x: 500, y: 500, width: 32, height: 32 })
